package org.unforced.uni

// Hand-written (not generated by `tauri android init`): stores the identity
// secret encrypted under a non-exportable AES-256-GCM key in Android Keystore.
// Ciphertext + IV live in a private SharedPreferences file; the plaintext
// never touches disk and is never logged.

import android.app.Activity
import android.app.KeyguardManager
import android.os.Build
import android.os.Handler
import android.os.Looper
import androidx.activity.result.ActivityResult
import androidx.biometric.BiometricPrompt
import androidx.biometric.BiometricManager.Authenticators.BIOMETRIC_STRONG
import androidx.biometric.BiometricManager.Authenticators.DEVICE_CREDENTIAL
import androidx.core.content.ContextCompat
import androidx.fragment.app.FragmentActivity
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.LifecycleOwner
import app.tauri.annotation.ActivityCallback
import android.content.Context
import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import android.util.Base64
import app.tauri.annotation.Command
import app.tauri.annotation.InvokeArg
import app.tauri.annotation.TauriPlugin
import app.tauri.plugin.Invoke
import app.tauri.plugin.JSObject
import app.tauri.plugin.Plugin
import java.security.KeyStore
import java.util.concurrent.atomic.AtomicLong
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

@InvokeArg
class SaveSecretArgs {
  lateinit var name: String
  lateinit var secret: String
}

@InvokeArg
class NameArgs {
  lateinit var name: String
}

@InvokeArg
class AuthenticateArgs {
  // T-234: approvals bring their own title; pairing sends none
  var title: String? = null
  lateinit var reason: String
  lateinit var authenticationId: String
}

@InvokeArg
class CancelAuthenticationArgs {
  lateinit var authenticationId: String
}

@TauriPlugin
class KeystorePlugin(private val activity: Activity) : Plugin(activity) {
  private var authenticating: Invoke? = null
  private var authenticationId: String? = null
  private var biometric: BiometricPrompt? = null
  private val handler = Handler(Looper.getMainLooper())
  private val timeout = Runnable { finishAuthentication(false, "Device unlock timed out") }

  private fun finishAuthentication(success: Boolean, message: String = "Device unlock cancelled") {
    val pending = authenticating ?: return
    authenticating = null
    authenticationId = null
    handler.removeCallbacks(timeout)
    biometric?.cancelAuthentication()
    biometric = null
    if (success) {
      unlockedAt.set(leftScreen.get())
      pending.resolve()
    } else pending.reject(message)
  }

  @Command
  fun authenticate(invoke: Invoke) {
    activity.runOnUiThread {
      if (authenticating != null) {
        invoke.reject("A device unlock is already in progress")
        return@runOnUiThread
      }
      val keyguard = activity.getSystemService(Context.KEYGUARD_SERVICE) as KeyguardManager
      if (!keyguard.isDeviceSecure) {
        invoke.reject("Set a screen lock on this device first")
        return@runOnUiThread
      }
      try {
        val args = invoke.parseArgs(AuthenticateArgs::class.java)
        val reason = args.reason
        val title = args.title ?: "Pair a device"
        authenticationId = args.authenticationId
        authenticating = invoke
        handler.postDelayed(timeout, 60_000)
        if (Build.VERSION.SDK_INT < 30) {
          // STRONG | DEVICE_CREDENTIAL is unsupported through API 29.
          // The OS credential intent handles PIN, pattern, and password on API 24+.
          @Suppress("DEPRECATION")
          val intent = keyguard.createConfirmDeviceCredentialIntent(title, reason)
          if (intent == null) finishAuthentication(false, "Set a screen lock on this device first")
          else startActivityForResult(invoke, intent, "credentialResult")
        } else {
          val host = activity as? FragmentActivity
          if (host == null) {
            finishAuthentication(false, "Device unlock is unavailable")
            return@runOnUiThread
          }
          val prompt = BiometricPrompt(host, ContextCompat.getMainExecutor(activity),
            object : BiometricPrompt.AuthenticationCallback() {
              override fun onAuthenticationSucceeded(result: BiometricPrompt.AuthenticationResult) {
                if (authenticating === invoke) finishAuthentication(true)
              }
              override fun onAuthenticationError(errorCode: Int, errString: CharSequence) {
                if (authenticating === invoke) finishAuthentication(false, "Device unlock cancelled or failed")
              }
            })
          biometric = prompt
          prompt.authenticate(BiometricPrompt.PromptInfo.Builder()
            .setTitle(title)
            .setDescription(reason)
            .setAllowedAuthenticators(BIOMETRIC_STRONG or DEVICE_CREDENTIAL)
            .build())
        }
      } catch (_: Exception) {
        finishAuthentication(false, "Device unlock is unavailable")
      }
    }
  }

  // T-335: the unlock grace (src-tauri/src/unlock_grace.rs). `leftScreen` counts each time the app leaves the screen
  // (another app, home, screen off or locked, and the unlock's own screen); `unlockedAt` is that count when the last
  // device unlock passed. Rust starts a grace only while the app is on the screen and hasn't left it since the unlock,
  // and ends it once the count moves. Both live for the process, so a recreated activity counts on.
  private val waitingForScreen = mutableListOf<Invoke>()

  override fun onPause() {
    leftScreen.incrementAndGet()
  }

  override fun onStop() {
    leftScreen.incrementAndGet()
  }

  override fun onResume() {
    val waiting = waitingForScreen.toList()
    waitingForScreen.clear()
    waiting.forEach { answerLifecycle(it, true) }
  }

  private fun answerLifecycle(invoke: Invoke, resumed: Boolean) {
    val out = JSObject()
    out.put("epoch", leftScreen.get())
    out.put("resumed", resumed)
    val at = unlockedAt.get()
    if (at >= 0) out.put("unlocked", at)
    invoke.resolve(out)
  }

  @Command
  fun lifecycle(invoke: Invoke) {
    activity.runOnUiThread {
      val wait = invoke.getArgs().optBoolean("wait", false)
      val resumed = (activity as? LifecycleOwner)?.lifecycle?.currentState?.isAtLeast(Lifecycle.State.RESUMED) == true
      if (resumed || !wait) {
        answerLifecycle(invoke, resumed)
      } else {
        // the unlock's own screen is closing: give the app up to two seconds to come back
        waitingForScreen.add(invoke)
        handler.postDelayed({ if (waitingForScreen.remove(invoke)) answerLifecycle(invoke, false) }, 2_000)
      }
    }
  }

  companion object {
    private val leftScreen = AtomicLong(0)
    private val unlockedAt = AtomicLong(-1)
  }

  @Command
  fun cancelAuthenticate(invoke: Invoke) {
    activity.runOnUiThread {
      val id = invoke.parseArgs(CancelAuthenticationArgs::class.java).authenticationId
      if (id == authenticationId) finishAuthentication(false)
      invoke.resolve()
    }
  }

  @ActivityCallback
  private fun credentialResult(invoke: Invoke, result: ActivityResult) {
    if (authenticating === invoke) finishAuthentication(result.resultCode == Activity.RESULT_OK)
  }

  private val keyAlias = "uni_identity"
  private val prefsName = "uni_keystore"

  private fun prefs() = activity.getSharedPreferences(prefsName, Context.MODE_PRIVATE)

  private fun key(create: Boolean): SecretKey? {
    val ks = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
    (ks.getKey(keyAlias, null) as? SecretKey)?.let { return it }
    if (!create) return null
    val gen = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore")
    gen.init(
      KeyGenParameterSpec.Builder(
        keyAlias,
        KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT
      )
        .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
        .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
        .setKeySize(256)
        .setRandomizedEncryptionRequired(true)
        .build()
    )
    return gen.generateKey()
  }

  @Command
  fun saveSecret(invoke: Invoke) {
    try {
      val args = invoke.parseArgs(SaveSecretArgs::class.java)
      val cipher = Cipher.getInstance("AES/GCM/NoPadding")
      cipher.init(Cipher.ENCRYPT_MODE, key(true))
      val ct = cipher.doFinal(args.secret.toByteArray(Charsets.UTF_8))
      val ok = prefs().edit()
        .putString("${args.name}.ct", Base64.encodeToString(ct, Base64.NO_WRAP))
        .putString("${args.name}.iv", Base64.encodeToString(cipher.iv, Base64.NO_WRAP))
        .commit()
      if (!ok) {
        invoke.reject("could not write encrypted secret")
        return
      }
      invoke.resolve()
    } catch (e: Exception) {
      invoke.reject("keystore save failed: ${e.javaClass.simpleName}")
    }
  }

  @Command
  fun loadSecret(invoke: Invoke) {
    try {
      val args = invoke.parseArgs(NameArgs::class.java)
      val p = prefs()
      val ct = p.getString("${args.name}.ct", null)
      val iv = p.getString("${args.name}.iv", null)
      val k = key(false)
      val out = JSObject()
      if (ct == null || iv == null || k == null) {
        out.put("secret", null as String?)
        invoke.resolve(out)
        return
      }
      val cipher = Cipher.getInstance("AES/GCM/NoPadding")
      cipher.init(Cipher.DECRYPT_MODE, k, GCMParameterSpec(128, Base64.decode(iv, Base64.NO_WRAP)))
      val pt = cipher.doFinal(Base64.decode(ct, Base64.NO_WRAP))
      out.put("secret", String(pt, Charsets.UTF_8))
      pt.fill(0)
      invoke.resolve(out)
    } catch (e: Exception) {
      invoke.reject("keystore load failed: ${e.javaClass.simpleName}")
    }
  }

  @Command
  fun clearSecret(invoke: Invoke) {
    try {
      val args = invoke.parseArgs(NameArgs::class.java)
      prefs().edit().remove("${args.name}.ct").remove("${args.name}.iv").commit()
      val ks = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
      if (ks.containsAlias(keyAlias)) ks.deleteEntry(keyAlias)
      invoke.resolve()
    } catch (e: Exception) {
      invoke.reject("keystore clear failed: ${e.javaClass.simpleName}")
    }
  }
}
